                            "props": {
                              "placeholder": "边框颜色",
                              "keywords": [
                                "inherit",
                                "none",
                                "transparent"
                              ],
                              "allowInherit": true
                            },
                            "_raw": {
                              "label": "边框颜色",
                              "desc": "\n\n<p>图形的描边颜色。支持的颜色格式同 <code class=\"codespan\">color</code>，不支持回调函数。</p>\n"
                            }
